package com.ruoyi.medical.persistence;
import com.ruoyi.medical.persistence.mapper.RuntimeRetentionMapper;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;
/** Uses the actual shared TenantScope prefix guard, not a substitute boolean. */
public class RuntimeRetentionSubjectTest extends RuntimeRetentionAuthorFixture {
 public RuntimeRetentionSubjectTest()throws Exception{super();}
 final Set<String> intercepted=new HashSet<>();
 RuntimeRetentionMapper guarded(){return (RuntimeRetentionMapper)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class<?>[]{RuntimeRetentionMapper.class},(proxy,method,args)->{String id="com.ruoyi.medical.persistence.mapper.RuntimeRetentionMapper."+method.getName();TenantScope.requireSubjectParameter(id,args[0]);intercepted.add(method.getName());try{return method.invoke(mapper,args);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});}
 @Test void missingAndForeignSubjectRejectBeforeMapper()throws Exception{within(()->{var guarded=guarded();assertThrows(TenantAccessException.class,()->guarded.fixed(Map.of("policyRevision",id(4))));assertThrows(TenantAccessException.class,()->guarded.fixed(Map.of("policyRevision",id(4),"userId",id(99))));assertTrue(intercepted.isEmpty());assertEquals(1,guarded.fixed(Map.of("policyRevision",id(4),"userId",id(2))).size());});}
 @Test void actualCreateReadRecoverReplaceAndRetireTraverseGuard()throws Exception{within(()->{var m=guarded();var current=new RuntimeRetentionAuthority(m,permissions,resources,grants,schema,identities,20);var decisions=new RuntimeRetentionDecisions(access,m,permissions,resources,current,schema,json);var writer=new RuntimeRetentionService(access,m,permissions,resources,current,schema,json,decisions);var reader=new RuntimeRetentionReads(access,m,permissions,resources,current,schema,json);current.requireForRun(a,id(3),"INTERNAL","RUN_CREATION");var first=writer.approve(actor,"1","guarded-original-key",bytes(request));writer.recover(actor,"1","guarded-original-key");reader.list(actor,"1","PROJECT",id(3),10,null);reader.read(actor,"1",first.required("policy_revision").asText());decisions.retire(actor,"1","guarded-retirement-key",bytes(retirementRequest()));decisions.recover(actor,"1","guarded-retirement-key");request.put("effective_from",now.plusHours(1).toInstant(java.time.ZoneOffset.UTC).toString());request.set("replaces",json.object().put("policy_revision",first.required("policy_revision").asText()).put("expected_revision","1"));writer.approve(actor,"1","guarded-replacement-key",bytes(request));assertTrue(intercepted.containsAll(Set.of("fixed","state","retirement","registry","operation","audit","event","insertVersion","insertOperation","insertPolicy","initializeState","insertRetirement","retireState","insertRetireOperation","retirementOperation","retirementAudit","retirementEvent","byKey","retirementByKey","list","candidates")));});}
 @Test void currentReaderSubjectDoesNotReplaceHistoricalCreator()throws Exception{when(a.actorId()).thenReturn(id(99));try(var ignored=TenantScope.open(new TenantScope.Identity(id(1),id(99),java.math.BigInteger.ONE,java.math.BigInteger.ONE,java.math.BigInteger.ONE))){var parameters=RuntimeRetentionAuthority.values(row);assertEquals(id(99),parameters.get("userId"));assertEquals(id(2),parameters.get("creator"));TenantScope.requireSubjectParameter("com.ruoyi.medical.persistence.mapper.RuntimeRetentionMapper.operation",parameters);var current=new RuntimeRetentionAuthority(guarded(),permissions,resources,grants,schema,identities,20);assertEquals(row.policyRevision(),current.requireForRun(a,id(3),"INTERNAL","RUN_CREATION").policyRevision());}}
 public static void main(String[]args)throws Exception{int n=0;for(var method:RuntimeRetentionSubjectTest.class.getDeclaredMethods())if(method.isAnnotationPresent(Test.class)){try{method.invoke(new RuntimeRetentionSubjectTest());System.out.println("PASS "+method.getName());n++;}catch(java.lang.reflect.InvocationTargetException e){throw new RuntimeException(method.getName(),e.getCause());}}System.out.println("PASS "+n+" actual shared subject guard tests");}
}
